sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    /*
     * =========================================================
     * CAMPUS360 TPO OPPORTUNITIES
     * =========================================================
     */

    data.opportunities = [];
    data.types = [];

    data.stats = {
        total: 0,
        open: 0,
        upcoming: 0,
        companies: 0
    };


    var opportunityGR = new GlideRecord(
        'x_snc_campus360_placement_opportunity'
    );

    opportunityGR.orderByDesc('drive_date');
    opportunityGR.query();


    var typeMap = {};
    var companyMap = {};


    while (opportunityGR.next()) {

        var title =
            opportunityGR.getValue('opportunity_title') || '';

        var opportunityId =
            opportunityGR.getValue('opportunity_id') || '';

        var company =
            opportunityGR.getDisplayValue('company_reference') ||
            '';

        var type =
            opportunityGR.getDisplayValue('opportunity_type') ||
            opportunityGR.getValue('opportunity_type') ||
            '';

        var skills =
            opportunityGR.getValue('required_skills') || '';

        var branches =
            opportunityGR.getValue('eligible_branches') || '';

        var minimumCgpa =
            opportunityGR.getValue('minimum_cgpa');

        var deadline =
            opportunityGR.getDisplayValue('application_deadline') ||
            '';

        var driveDate =
            opportunityGR.getDisplayValue('drive_date') ||
            '';

        var location =
            opportunityGR.getValue('location') || '';

        var ctc =
            opportunityGR.getValue('ctc_stipend') || '';

        var source =
            opportunityGR.getDisplayValue('opportunity_source') ||
            opportunityGR.getValue('opportunity_source') ||
            '';

        var status =
            opportunityGR.getDisplayValue('status') ||
            opportunityGR.getValue('status') ||
            '';


        /*
         * INITIALS
         */

        var initials = '';

        if (company) {

            var words =
                company.trim().split(/\s+/);

            if (words.length === 1) {

                initials =
                    words[0].substring(0, 2);

            } else {

                initials =
                    words[0].charAt(0) +
                    words[1].charAt(0);

            }

        }

        initials =
            initials.toUpperCase();


        /*
         * CGPA DISPLAY
         */

        var cgpaLabel = 'No CGPA limit';

        if (
            minimumCgpa !== null &&
            minimumCgpa !== undefined &&
            minimumCgpa !== ''
        ) {

            cgpaLabel =
                'CGPA ≥ ' + minimumCgpa;

        }


        /*
         * OPPORTUNITY OBJECT
         */

        data.opportunities.push({

            sys_id:
                opportunityGR.getUniqueValue(),

            id:
                opportunityId,

            title:
                title,

            company:
                company,

            type:
                type,

            skills:
                skills,

            branches:
                branches,

            minimumCgpa:
                minimumCgpa,

            cgpaLabel:
                cgpaLabel,

            deadline:
                deadline,

            driveDate:
                driveDate,

            location:
                location,

            ctc:
                ctc,

            source:
                source,

            status:
                status,

            description:
                opportunityGR.getValue('job_description') || '',

            initials:
                initials

        });


        /*
         * STATS
         */

        data.stats.total++;


        if (status === 'Open') {

            data.stats.open++;

        }


        if (company) {

            companyMap[company] = true;

        }


        if (type) {

            typeMap[type] = true;

        }

    }


    /*
     * TYPES
     */

    for (var typeName in typeMap) {

        if (typeMap.hasOwnProperty(typeName)) {

            data.types.push(typeName);

        }

    }

    data.types.sort();


    /*
     * COMPANIES
     */

    for (var companyName in companyMap) {

        if (companyMap.hasOwnProperty(companyName)) {

            data.stats.companies++;

        }

    }


    /*
     * UPCOMING
     *
     * We deliberately don't invent a time-based rule here.
     * This is simply based on opportunities having a
     * Drive Date value.
     */

    for (var i = 0; i < data.opportunities.length; i++) {

        if (
            data.opportunities[i].driveDate &&
            data.opportunities[i].status === 'Open'
        ) {

            data.stats.upcoming++;

        }

    }


})();

